<?php header('Content-Type: application/json');try{$c=require __DIR__.'/config.php';$p=new PDO("mysql:host={$c['db_host']};dbname={$c['db_name']};charset=utf8mb4",$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$a=$_GET['action']??'stats';if($a==='stats'){echo json_encode(['products'=>(int)$p->query("SELECT COUNT(*) FROM products")->fetchColumn(),'orders'=>(int)$p->query("SELECT COUNT(*) FROM orders")->fetchColumn(),'agents'=>(int)$p->query("SELECT COUNT(*) FROM agents WHERE active=1")->fetchColumn()]);exit;}if($a==='quick'){echo json_encode(['messages'=>$p->query("SELECT message FROM quick_messages WHERE active=1 ORDER BY sort_order")->fetchAll(PDO::FETCH_COLUMN)]);exit;}$d=json_decode(file_get_contents('php://input'),true);if($a==='product'){$s=$p->prepare("INSERT INTO products(name,category,price,icon,details) VALUES(?,?,?,?,?)");$s->execute([$d['name'],$d['category'],$d['price'],$d['icon']??'📦',$d['details']??'']);}elseif($a==='agent'){$s=$p->prepare("INSERT INTO agents(name,phone,email) VALUES(?,?,?)");$s->execute([$d['name'],$d['phone']??'',$d['email']??'']);}elseif($a==='quick'){$p->exec("DELETE FROM quick_messages");$s=$p->prepare("INSERT INTO quick_messages(message,sort_order,active) VALUES(?,?,1)");foreach(($d['messages']??[]) as $i=>$m)$s->execute([$m,$i]);}else throw new Exception('Unknown action');echo json_encode(['success'=>true]);}catch(Throwable $e){http_response_code(400);echo json_encode(['error'=>$e->getMessage()]);}